{"file_path":"F:\programms\github\tzyoutube\src\app\static\app.css","content":"/* TZ Video — YouTube-like layout, system font stack, CSS-variable themes.
 * Light is the default; [data-theme="dark"] (set by theme.js) switches. */

:root {
  --bg: #ffffff;
  --fg: #0f0f0f;
  --fg-soft: #606060;
  --line: #e5e5e5;
  --chip: #f2f2f2;
  --chip-active: #0f0f0f;
  --chip-fg-active: #ffffff;
  --card-hover: #f9f9f9;
  --header-bg: #ffffff;
  --input-bg: #ffffff;
  --accent: #e62117;
  --accent-fg: #ffffff;
  --btn: #f2f2f2;
  --btn-hover: #e5e5e5;
  --danger: #c00;
  --ok: #0a7d2c;
  --thumb-bg: #d9d9d9;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  --sidebar-w: 232px;
  --header-h: 56px;
  font-size: 14px;
}

:root[data-theme="dark"] {
  --bg: #0f0f0f;
  --fg: #f1f1f1;
  --fg-soft: #aaaaaa;
  --line: #272727;
  --chip: #272727;
  --chip-active: #f1f1f1;
  --chip-fg-active: #0f0f0f;
  --card-hover: #1f1f1f;
  --header-bg: #0f0f0f;
  --input-bg: #121212;
  --btn: #272727;
  --btn-hover: #3d3d3d;
  --thumb-bg: #2c2c2c;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #0f0f0f;
    --fg: #f1f1f1;
    --fg-soft: #aaaaaa;
    --line: #272727;
    --chip: #272727;
    --chip-active: #f1f1f1;
    --chip-fg-active: #0f0f0f;
    --card-hover: #1f1f1f;
    --header-bg: #0f0f0f;
    --input-bg: #121212;
    --btn: #272727;
    --btn-hover: #3d3d3d;
    --thumb-bg: #2c2c2c;
    --shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
  }
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: Roboto, Arial, "Segoe UI", "Helvetica Neue", sans-serif;
  line-height: 1.4;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { font: inherit; color: inherit; cursor: pointer; background: none; border: none; }
input, textarea, select {
  font: inherit;
  color: var(--fg);
  background: var(--input-bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 12px;
}

/* --- header --- */
.topbar {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 16px;
  height: var(--header-h);
  padding: 0 16px;
  background: var(--header-bg);
}
.tb-left { display: flex; align-items: center; gap: 8px; }
.tb-right { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.logo { display: flex; align-items: center; gap: 6px; }
.logo-text { font-size: 18px; font-weight: 700; letter-spacing: -0.5px; }

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
}
.icon-btn:hover { background: var(--btn); }

.search {
  display: flex;
  flex: 1 1 auto;
  max-width: 640px;
  margin: 0 auto;
}
.search input {
  flex: 1;
  border-radius: 20px 0 0 20px;
  border-right: none;
  outline: none;
}
.search input:focus { border-color: #1c62b9; }
.search-btn {
  border: 1px solid var(--line);
  border-left: none;
  border-radius: 0 20px 20px 0;
  width: 56px;
  background: var(--btn);
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 18px;
  background: var(--btn);
  white-space: nowrap;
}
.btn:hover { background: var(--btn-hover); }
.btn.primary { background: var(--accent); color: var(--accent-fg); }
.btn.primary:hover { background: #c81e14; }
.btn.ghost { background: transparent; }
.btn.ghost:hover { background: var(--btn); }
.btn.danger { background: var(--danger); color: #fff; }

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  text-transform: uppercase;
}
.avatar.sm { width: 36px; height: 36px; flex: 0 0 auto; }

/* theme toggle icon visibility */
:root[data-theme="dark"] .ic-sun { display: block; }
:root[data-theme="dark"] .ic-moon { display: none; }
:root:not([data-theme="dark"]) .ic-sun { display: none; }
:root:not([data-theme="dark"]) .ic-moon { display: block; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .ic-sun { display: block; }
  :root:not([data-theme="light"]) .ic-moon { display: none; }
}

/* --- layout + sidebar --- */
.layout { display: flex; }
.sidebar {
  position: sticky;
  top: var(--header-h);
  align-self: flex-start;
  width: var(--sidebar-w);
  height: calc(100vh - var(--header-h));
  padding: 12px;
  overflow-y: auto;
  flex: 0 0 auto;
}
.side-item {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 15px;
}
.side-item:hover { background: var(--btn); }
.side-item.active { background: var(--chip); font-weight: 600; }
body.sidebar-collapsed .sidebar { width: 76px; }
body.sidebar-collapsed .side-item span { display: none; }
body.sidebar-collapsed .side-item { justify-content: center; gap: 0; }

.content {
  flex: 1 1 auto;
  min-width: 0;
  padding: 20px 24px 60px;
}

/* --- chips --- */
.chips {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 12px;
  margin-bottom: 8px;
  scrollbar-width: none;
}
.chips::-webkit-scrollbar { display: none; }
.chip {
  padding: 7px 12px;
  border-radius: 8px;
  background: var(--chip);
  white-space: nowrap;
}
.chip.active { background: var(--chip-active); color: var(--chip-fg-active); }

.page-title { font-size: 20px; margin: 4px 0 16px; }

/* --- card grid --- */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
  gap: 20px 16px;
}
.card { display: block; border-radius: 12px; }
.card:hover .card-title { color: var(--fg); }
.thumb {
  position: relative;
  aspect-ratio: 16 / 9;
  border-radius: 12px;
  overflow: hidden;
  background: var(--thumb-bg);
}
.thumb img { width: 100%; height: 100%; object-fit: cover; }
.thumb-ph {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fg-soft);
}
.dur {
  position: absolute;
  right: 6px;
  bottom: 6px;
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.8);
  color: #fff;
  font-size: 12px;
}
.card-meta { display: flex; gap: 10px; padding: 10px 4px 0; }
.card-text { min-width: 0; }
.card-title {
  font-weight: 600;
  font-size: 15px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card-sub { color: var(--fg-soft); font-size: 13px; margin-top: 2px; }
.card-channel:hover { color: var(--fg); }

/* --- empty state / toast --- */
.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 64px 16px;
  color: var(--fg-soft);
  text-align: center;
}
.empty-title { font-size: 18px; font-weight: 600; color: var(--fg); margin: 0; }
.empty-sub { margin: 0; }

.toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  padding: 10px 18px;
  border-radius: 8px;
  background: #323232;
  color: #fff;
  box-shadow: var(--shadow);
  z-index: 100;
  max-width: 90vw;
}
.toast.ok { background: var(--ok); }

/* --- auth pages --- */
.auth-wrap {
  max-width: 400px;
  margin: 48px auto;
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: 16px;
}
.auth-wrap h1 { margin: 0 0 4px; font-size: 22px; }
.auth-wrap .auth-sub { color: var(--fg-soft); margin: 0 0 20px; }
.auth-wrap form { display: flex; flex-direction: column; gap: 12px; }
.auth-wrap label { display: flex; flex-direction: column; gap: 4px; font-size: 13px; color: var(--fg-soft); }
.auth-wrap .auth-switch { margin-top: 16px; font-size: 13px; color: var(--fg-soft); }
.auth-wrap .auth-switch a { color: #1c62b9; font-weight: 600; }
.auth-error {
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(204, 0, 0, 0.1);
  color: var(--danger);
  font-size: 13px;
}

/* --- watch page --- */
.watch { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 24px; align-items: start; }
.player-wrap { border-radius: 12px; overflow: hidden; background: #000; aspect-ratio: 16 / 9; }
.player-wrap video { width: 100%; height: 100%; }
.watch-title { font-size: 20px; font-weight: 700; margin: 14px 0 10px; }
.watch-row { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.channel-box { display: flex; align-items: center; gap: 10px; margin-right: auto; }
.channel-box .ch-name { font-weight: 600; }
.channel-box .ch-subs { color: var(--fg-soft); font-size: 12px; }
.sub-btn.subscribed { background: var(--chip); color: var(--fg); }
.actions { display: flex; gap: 8px; }
.seg { display: inline-flex; border-radius: 18px; background: var(--btn); overflow: hidden; }
.seg button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  font-weight: 600;
}
.seg button + button { border-left: 1px solid var(--line); }
.seg button.active { background: var(--chip-active); color: var(--chip-fg-active); }
.desc-box {
  margin-top: 14px;
  padding: 12px;
  border-radius: 12px;
  background: var(--chip);
  white-space: pre-wrap;
  word-break: break-word;
}
.desc-box .desc-meta { font-weight: 600; margin-bottom: 4px; }

.comments { margin-top: 24px; }
.comments h2 { font-size: 17px; margin: 0 0 14px; }
.comment-form { display: flex; gap: 10px; margin-bottom: 20px; }
.comment-form input { flex: 1; }
.comment { display: flex; gap: 10px; margin-bottom: 16px; }
.comment .c-body { min-width: 0; }
.comment .c-author { font-weight: 600; font-size: 13px; }
.comment .c-date { color: var(--fg-soft); font-size: 12px; margin-left: 6px; }
.comment .c-text { margin: 2px 0 4px; white-space: pre-wrap; word-break: break-word; }
.comment .c-reply { color: var(--fg-soft); font-size: 12px; font-weight: 600; }
