  background: var(--chip);
  white-space: pre-wrap;
  word-break: break-word;
}
.desc-box .desc-meta { font-weight: 600; margin-bottom: 4px; }

.comments { margin-top: 24px; }
.comments h2 { font-size: 17px; margin: 0 0 14px; }
.comment-form { display: flex; gap: 10px; margin-bottom: 20px; }
.comment-form input { flex: 1; }
.comment { display: flex; gap: 10px; margin-bottom: 16px; }
.comment .c-body { min-width: 0; }
.comment .c-author { font-weight: 600; font-size: 13px; }
.comment .c-date { color: var(--fg-soft); font-size: 12px; margin-left: 6px; }
.comment .c-text { margin: 2px 0 4px; white-space: pre-wrap; word-break: break-word; }
.comment .c-reply { color: var(--fg-soft); font-size: 12px; font-weight: 600; }
.comment.reply { margin-left: 46px; }

.recs { display: flex; flex-direction: column; gap: 12px; }
.rec { display: flex; gap: 8px; }
.rec .thumb { width: 168px; flex: 0 0 auto; border-radius: 8px; }
.rec .r-title { font-weight: 600; font-size: 14px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.rec .r-sub { color: var(--fg-soft); font-size: 12px; }

/* --- upload --- */
.dropzone {
  border: 2px dashed var(--line);
  border-radius: 16px;
  padding: 48px 24px;
  text-align: center;
  color: var(--fg-soft);
}
.dropzone.over { border-color: var(--accent); color: var(--fg); }
.progress { height: 8px; border-radius: 4px; background: var(--chip); overflow: hidden; margin: 12px 0; }
.progress > div { height: 100%; width: 0; background: var(--accent); transition: width 0.15s; }

/* --- tables (my videos, moderation, admin) --- */
.table { width: 100%; border-collapse: collapse; }
.table th, .table td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; }
.table th { color: var(--fg-soft); font-size: 12px; text-transform: uppercase; letter-spacing: 0.4px; }
.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 600;
  background: var(--chip);
}
.badge.ready { background: rgba(10, 125, 44, 0.15); color: var(--ok); }
.badge.processing { background: rgba(28, 98, 185, 0.15); color: #1c62b9; }
.badge.failed, .badge.hidden, .badge.deleted { background: rgba(204, 0, 0, 0.12); color: var(--danger); }
.row-actions { display: flex; gap: 6px; flex-wrap: wrap; }
.row-actions .btn { padding: 5px 10px; font-size: 13px; }

/* --- channel --- */
.channel-head { display: flex; gap: 20px; align-items: center; padding: 16px 0 20px; flex-wrap: wrap; }
.channel-head .avatar { width: 96px; height: 96px; font-size: 36px; }
.channel-head h1 { margin: 0 0 4px; font-size: 26px; }
.channel-head .ch-desc { color: var(--fg-soft); max-width: 640px; white-space: pre-wrap; }
.tabs { display: flex; gap: 24px; border-bottom: 1px solid var(--line); margin-bottom: 18px; }
.tabs a { padding: 10px 4px; color: var(--fg-soft); font-weight: 600; border-bottom: 2px solid transparent; }
.tabs a.active { color: var(--fg); border-color: var(--fg); }

/* --- error page --- */
.error-wrap { text-align: center; padding: 80px 16px; }
.error-code { font-size: 72px; font-weight: 800; color: var(--accent); margin: 0; }
.error-text { color: var(--fg-soft); }

/* --- responsive --- */
@media (max-width: 1000px) {
  .watch { grid-template-columns: 1fr; }
  .recs { flex-direction: row; flex-wrap: wrap; }
  .rec { flex: 1 1 260px; }
}
@media (max-width: 800px) {
  :root { --sidebar-w: 0px; }
  .sidebar {
    position: fixed;
    left: 0;
    top: var(--header-h);
    z-index: 40;
    width: 232px;
    background: var(--header-bg);
    transform: translateX(-100%);
    transition: transform 0.15s;
    box-shadow: var(--shadow);
  }
  body:not(.sidebar-collapsed) .sidebar { transform: translateX(0); }
  body.sidebar-collapsed .sidebar { transform: translateX(-100%); width: 232px; }
  body.sidebar-collapsed .side-item span { display: inline; }
  .btn-label { display: none; }
  .search { margin: 0 8px; }
  .content { padding: 14px 12px 48px; }
  .logo-text { display: none; }
}
