.channel-box .ch-name { font-weight: 600; }
.channel-box .ch-subs { color: var(--fg-soft); font-size: 12px; }
.sub-btn.subscribed { background: var(--chip); color: var(--fg); }
.actions { display: flex; gap: 8px; }
.seg { display: inline-flex; border-radius: 18px; background: var(--btn); overflow: hidden; }
.seg button {
  display: inline-flex;
