  font-weight: 600;
}
.seg button + button { border-left: 1px solid var(--line); }
.seg button.active { background: var(--chip-active); color: var(--chip-fg-active); }
.desc-box {
  margin-top: 14px;
  padding: 12px;
  border-radius: 12px;
  background: var(--chip);
  white-space: pre-wrap;
  word-break: break-word;
}
.desc-box .desc-meta { font-weight: 600; margin-bottom: 4px; }

.comments { margin-top: 24px; }
.comments h2 { font-size: 17px; margin: 0 0 14px; }
.comment-form { display: flex; gap: 10px; margin-bottom: 20px; }
.comment-form input { flex: 1; }
.comment { display: flex; gap: 10px; margin-bottom: 16px; }
.comment .c-body { min-width: 0; }
.comment .c-author { font-weight: 600; font-size: 13px; }
.comment .c-date { color: var(--fg-soft); font-size: 12px; margin-left: 6px; }
.comment .c-text { margin: 2px 0 4px; white-space: pre-wrap; word-break: break-word; }
.comment .c-reply { color: var(--fg-soft); font-size: 12px; font-weight: 600; }
.comment.reply { margin-left: 46px; }

.recs { display: flex; flex-direction: column; gap: 12px; }
.rec { display: flex; gap: 8px; }
.rec .thumb { width: 168px; flex: 0 0 auto; border-radius: 8px; }
.rec .r-title { font-weight: 600; font-size: 14px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.rec .r-sub { color: var(--fg-soft); font-size: 12px; }","new_string":"/* --- watch page --- */
.watch { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 24px; align-items: start; }
.player { border-radius: 12px; overflow: hidden; background: #000; aspect-ratio: 16 / 9; }
.player video { width: 100%; height: 100%; display: block; }
.player-stub { aspect-ratio: 16 / 9; display: flex; align-items: center; justify-content: center; color: #fff; background: #111; border-radius: 12px; padding: 16px; text-align: center; }
.watch-title { font-size: 20px; font-weight: 700; margin: 14px 0 10px; }
.watch-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.channel-box { display: flex; align-items: center; gap: 10px; margin-right: auto; }
.channel-meta { display: flex; flex-direction: column; }
.channel-name { font-weight: 600; color: var(--fg); }
.sub-count { color: var(--fg-soft); font-size: 12px; }
.actions-right { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.segmented { display: inline-flex; border-radius: 18px; background: var(--btn); overflow: hidden; }
.segmented .seg {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  font-weight: 600;
}
.segmented .seg + .seg { border-left: 1px solid var(--line); }
.segmented .seg.active { background: var(--chip-active); color: var(--chip-fg-active); }
.report { display: flex; gap: 6px; align-items: center; }
.watch-desc {
  margin-top: 14px;
  padding: 12px;
  border-radius: 12px;
  background: var(--chip);
}
.desc-meta { font-weight: 600; margin-bottom: 4px; }
.desc-text { white-space: pre-wrap; word-break: break-word; margin: 0; }

.comments { margin-top: 24px; }
.comments h2 { font-size: 17px; margin: 0 0 14px; }
.comment-form { display: flex; gap: 10px; margin-bottom: 20px; }
.comment-form input { flex: 1; }
.comment-list { list-style: none; margin: 0; padding: 0; }
.comment { display: flex; gap: 10px; margin-bottom: 16px; }
.comment-body { min-width: 0; }
.comment-head .comment-author { font-weight: 600; font-size: 13px; }
.comment-text { margin: 2px 0 4px; white-space: pre-wrap; word-break: break-word; }
.comment.reply { margin-left: 46px; }
.muted { color: var(--fg-soft); }
.avatar.sm { width: 28px; height: 28px; font-size: 13px; flex: 0 0 auto; }
.btn.sm { padding: 4px 10px; font-size: 12px; }

.recs { display: flex; flex-direction: column; gap: 12px; }
.rec { display: flex; gap: 8px; color: var(--fg); }
.rec-thumb { position: relative; width: 168px; flex: 0 0 auto; border-radius: 8px; overflow: hidden; background: var(--chip); aspect-ratio: 16 / 9; }
.rec-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.rec-thumb .dur { position: absolute; right: 4px; bottom: 4px; background: rgba(0,0,0,.8); color: #fff; font-size: 11px; padding: 1px 5px; border-radius: 4px; }
.rec-meta { display: flex; flex-direction: column; min-width: 0; }
.rec-title { font-weight: 600; font-size: 14px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.rec-channel, .rec-sub { color: var(--fg-soft); font-size: 12px; }"}

