/* F5: channel page, subscriptions, playlist page */
.channel-head { display: flex; gap: 20px; align-items: flex-start; padding: 20px 0; }
.avatar.lg {
  width: 96px; height: 96px; border-radius: 50%; background: var(--chip);
  display: flex; align-items: center; justify-content: center;
  font-size: 40px; font-weight: 700; color: var(--fg-soft); flex-shrink: 0;
}
.channel-info { flex: 1; min-width: 0; }
.channel-name { margin: 0 0 4px; font-size: 24px; }
