{"content":"{% extends "base.html" %}
{% block title %}Модерация{% endblock %}
{% block content %}
<h1 class="page-title">Модерация</h1>
<nav class="tabs" aria-label="Разделы модерации">
  <a class="tab{% if not is_admin %} active{% endif %}" href="/mod">Жалобы</a>
  {% if is_admin %}
  <a class="tab active" href="/mod#admin">Пользователи</a>
  {% endif %}
</nav>

<form class="row-actions" method="get" action="/mod">
  <label class="muted">Статус:
    <select name="status" id="status-filter">
      {% for s in ["new", "resolved", "dismissed"] %}
      <option value="{{ s }}"{% if status_filter == s %} selected{% endif %}>
        {{ {"new": "новые", "resolved": "решённые", "dismissed": "отклонённые"}[s] }}
      </option>
      {% endfor %}
    </select>
  </label>
  <button class="btn sm" type="submit">Фильтр</button>
  <span class="muted">{{ total }} жалоб</span>
</form>

{% if reports %}
<table class="table" data-testid="reports-table">
  <thead>
    <tr><th>Видео</th><th>Причина</th><th>Комментарий</th><th>От</th><th>Статус</th><th>Действия</th></tr>
  </thead>
  <tbody>
    {% for r in reports %}
    <tr data-report-id="{{ r.id }}">
      <td><a href="/watch/{{ r.video_id }}">видео</a></td>
      <td>{{ r.reason }}</td>
      <td>{{ r.comment or "" }}</td>
      <td>{{ r.reporter.channel_name if r.reporter else r.reporter_id }}</td>
      <td>
        <span class="badge {{ r.status }}">{{ r.status }}</span>
        {% if r.resolution %}<div class="muted">{{ r.resolution }}: {{ r.resolution_note or "" }}</div>{% endif %}
        <div class="muted">{{ r.created }}</div>
      </td>
      <td>
        {% if r.status == "new" %}
        <div class="row-actions">
          <button class="btn sm danger" type="button" data-action="hide">Скрыть</button>
          <button class="btn sm" type="button" data-action="unhide">Вернуть</button>
          <button class="btn sm ghost" type="button" data-action="dismiss">Отклонить</button>
        </div>
        <input class="resolve-note" type="text" name="note" maxlength="500" placeholder="причина (журнал)">
        {% else %}
        <span class="muted">решено {{ r.resolved_at }}</span>
        {% endif %}
      </td>
    </tr>
    {% endfor %}
